#include <stdio.h>
#include <string.h>
#include <assert.h>
#include "compress.c"

void check(const char *src, const char *expected) {
    char buf[1024];
    compress_string(src, buf);
    if (strcmp(buf, expected) != 0) {
        printf("FAIL: input=\"%s\", expected=\"%s\", got=\"%s\"\n", src, expected, buf);
        assert(0);
    } else {
        printf("PASS: \"%s\" -> \"%s\"\n", src, buf);
    }
}

int main(void) {
    /* Example from the spec */
    check("aabcccccaaa", "a2b1c5a3");

    /* Single character */
    check("a", "a1");

    /* Empty string */
    check("", "");

    /* All same characters */
    check("aaaa", "a4");

    /* All different characters */
    check("abc", "a1b1c1");

    /* Mixed case */
    check("AABbbCCC", "A2B1b3C3");

    /* Large count (multi-digit) */
    check("ab", "a1b1");

    printf("\nAll tests passed!\n");
    return 0;
}
EOF
gcc -Wall -Wextra -o test_compress test_compress.c && ./test_compress

